  .name("fetch-failed-logs")
  .description("Download and parse CI logs")
  .requiredOption("--run-id <id>", "Workflow run ID")
  .action(async (options) => {
    const file = Bun.file(`logs/${options.runId}.txt`);
  });

if (import.meta.main) {
  program.parse();
}

