#!/usr/bin/env bun
import { Command } from "commander";

export const program = new Command();
program
  .name("cleanup-ephemeral-dbs")
  .description("Prune stale preview databases")
  .option("--dry-run", "Simulate actions without deleting", false)
  .action(async (opts) => {
    if (opts.dryRun) {
      console.log("[DRY RUN] Would delete stale DBs");
      return;
    }
  });

program.parse();
// Run companion suite: bun test scripts/cleanup-ephemeral-dbs.spec.ts

#!/usr/bin/env bun
import { Command } from "commander";

export const program = new Command();
program
  .name("transform-assets")
  .action(async () => {
    const content = await Bun.file("input.json").text();
    await Bun.write("output.json", content.toUpperCase());
    await Bun.$`echo 'Done'`;
  });

program.parse();
// Unit tests: bun test scripts/transform-assets.spec.ts

